import React, { useEffect } from 'react'
import {
    Table, TableHeader, TableColumn, TableBody, TableRow, TableCell, Tooltip, getKeyValue, Pagination,
    Input,
    Button,
    DropdownTrigger,
    Dropdown,
    DropdownMenu,
    DropdownItem,
    Chip,
    User,

} from "@heroui/react";
import { ChevronDownIcon, DeleteIcon, EditIcon, EyeIcon, SearchIcon } from '../../../components';
import { capitalize } from "../../../helpers/utils";
import { PlusIcon } from '@heroicons/react/outline';
import { statusOptions } from "./data";
import { useStateContext } from '../../../contexts/ContextProvider';


const INITIAL_VISIBLE_COLUMNS = ["name", "role", "status", "actions"];
function DrinksTable({ columns, data, editAction, detailsAction, deleteAction, addAction, modalTitle, handleFilter }) {
    const [filterValue, setFilterValue] = React.useState("");
    const [visibleColumns, setVisibleColumns] = React.useState(new Set(INITIAL_VISIBLE_COLUMNS));
    const [statusFilter, setStatusFilter] = React.useState("all");
    const [rowsPerPage, setRowsPerPage] = React.useState(100);
    const { currentColor } = useStateContext()
    const hasSearchFilter = Boolean(filterValue);
    const onRowsPerPageChange = React.useCallback((e) => {
        setRowsPerPage(Number(e.target.value));
        setPage(1);
    }, []);
    const onSearchChange = React.useCallback((value) => {
        if (value) {
            setFilterValue(value);
            setPage(1);
        } else {
            setFilterValue("");
        }
    }, []);


    useEffect(() => {
        if (filterValue) {
            handleFilter(filterValue)
        }
    }, [filterValue])

    const topContent = React.useMemo(() => {
        return (
            <div className="flex flex-col gap-4">
                <div className="flex justify-between gap-3 items-end">
                    <Input
                        isClearable
                        classNames={{
                            base: "w-full sm:max-w-[44%]",
                            inputWrapper: "border-1",
                        }}
                        placeholder="Search by name..."
                        size="lg"
                        startContent={<SearchIcon className="text-default-300" />}
                        value={filterValue}
                        variant="bordered"
                        onClear={() => setFilterValue("")}
                        onValueChange={onSearchChange}
                    />
                    <div className="flex gap-3">
                        <Dropdown>
                            <DropdownTrigger className="hidden sm:flex">
                                <Button
                                    endContent={<ChevronDownIcon className="text-small" />}
                                    size="lg"
                                    variant="flat"
                                >
                                    Status
                                </Button>
                            </DropdownTrigger>
                            <DropdownMenu
                                disallowEmptySelection
                                aria-label="Table Columns"
                                closeOnSelect={false}
                                selectedKeys={statusFilter}
                                selectionMode="multiple"
                                onSelectionChange={setStatusFilter}
                            >
                                {statusOptions.map((status) => (
                                    <DropdownItem key={status.uid} className="capitalize">
                                        {capitalize(status.name)}
                                    </DropdownItem>
                                ))}
                            </DropdownMenu>
                        </Dropdown>
                        <Dropdown>
                            <DropdownTrigger className="hidden sm:flex">
                                <Button
                                    endContent={<ChevronDownIcon className="text-small" />}
                                    size="lg"
                                    variant="flat"
                                >
                                    Columns
                                </Button>
                            </DropdownTrigger>
                            <DropdownMenu

                                disallowEmptySelection
                                aria-label="Table Columns"
                                closeOnSelect={false}
                                selectedKeys={visibleColumns}
                                selectionMode="multiple"
                                onSelectionChange={setVisibleColumns}
                            >
                                {columns.map((column) => (
                                    <DropdownItem key={column.uid} className="capitalize">
                                        {capitalize(column.name)}
                                    </DropdownItem>
                                ))}
                            </DropdownMenu>
                        </Dropdown>
                        <Button
                            style={{ background: currentColor }}
                            onClick={addAction}
                            className="bg-transparent rounded text-white"
                            endContent={<PlusIcon />}
                            size="lg"
                        >
                            Add New
                        </Button>
                    </div>
                </div>
                <div className="flex justify-between items-center">
                    <span className="text-default-400 text-small">Total {data.length} items</span>
                    <span className="text-default-400 text-small">Total Value: KES {parseFloat(data.reduce(
                        (accumulator, currentValue) => accumulator + (parseFloat(currentValue.unit_selling_price)*parseFloat(currentValue.pack_quantity)),
                        0,
                      )).toFixed(2)}</span>
                    <label className="flex items-center text-default-400 text-small">
                        Rows per page:
                        <select
                            className="bg-transparent outline-none text-default-400 text-small"
                            onChange={onRowsPerPageChange}
                        >
                            <option value="200">200</option>
                            <option value="250">250</option>
                            <option value="300">300</option>
                        </select>
                    </label>
                </div>
            </div>
        );
    }, [
        filterValue,
        statusFilter,
        visibleColumns,
        onSearchChange,
        onRowsPerPageChange,
        data.length,
        hasSearchFilter,
    ]);

    console.log('data here', data)
    const renderCell = React.useCallback((item, columnKey) => {
        const cellValue = item[columnKey];

        switch (columnKey) {

            case "title":
                return  <User
                avatarProps={{ radius: "sm", src: item.images && item.images.length?item.images[0].thumbnail:"" }}
                description={item.product_title}
                name={item.title}
            >
                {item.title}
            </User>
                // return (
                //     <div className="flex flex-col">
                //         <p className="text-bold text-sm ">{cellValue}</p>
                //         {/* <p className="text-bold text-sm capitalize text-default-400">{item.title}</p> */}
                //     </div>
                // );
            case "description":
                return (
                    <div className="flex flex-col">
                        <p className="text-bold text-sm">{cellValue}</p>
                        {/* <p className="text-bold text-sm capitalize text-default-400">{item.description}</p> */}
                    </div>
                );
            // case "status":
            //     return (
            //         <Chip className="capitalize" color={statusColorMap[item.status]} size="sm" variant="flat">
            //             {cellValue}
            //         </Chip>
            //     );
            case "actions":
                return (
                    <div className="relative flex items-center gap-2">
                        <Tooltip content="Details">
                            <span className="text-lg text-default-400 cursor-pointer active:opacity-50">
                                <EyeIcon onClick={() => detailsAction(item)} />
                            </span>
                        </Tooltip>
                        <Tooltip content="Edit user">
                            <span className="text-lg text-default-400 cursor-pointer active:opacity-50">
                                <EditIcon onClick={() => editAction(item)} />
                            </span>
                        </Tooltip>
                        <Tooltip color="danger" content="Delete user">
                            <span className="text-lg text-danger cursor-pointer active:opacity-50">
                                <DeleteIcon onClick={() => deleteAction(item)} />
                            </span>
                        </Tooltip>
                    </div>
                );
            default:
                return cellValue;
        }
    }, []);


    const [page, setPage] = React.useState(1);
    // const rowsPerPage = 10;

    const pages = Math.ceil(data.length / rowsPerPage);

    const items = React.useMemo(() => {
        const start = (page - 1) * rowsPerPage;
        const end = start + rowsPerPage;

        return data.slice(start, end);
    }, [page, data]);

    return (
        <Table title='Users' aria-label="Example table with custom cells" bottomContent={
            <div className="flex w-full justify-center">
                <Pagination
                    isCompact
                    showControls
                    showShadow
                    color="secondary"
                    page={page}
                    total={pages}
                    onChange={(page) => setPage(page)}
                />
            </div>
        } topContent={topContent}>
            <TableHeader columns={columns}>
                {(column) => (
                    <TableColumn key={column.uid} align={column.uid === "actions" ? "center" : "start"}>
                        {column.name}
                    </TableColumn>
                )}
            </TableHeader>
            {items.length ? <TableBody items={items}>
                {(item) => (
                    <TableRow key={item.id}>
                        {(columnKey) => <TableCell>{renderCell(item, columnKey)}</TableCell>}
                    </TableRow>
                )}
            </TableBody> : <TableBody emptyContent={"No rows to display."}>{[]}</TableBody>}
        </Table>
    );
}

export default DrinksTable