import React, { useEffect, useState } from 'react'
import DrinksTable from './DrinksTable'

import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import DrinksFormModal from './DrinksFormModal';
import transportApi from '../../../api/transport/transportApi';
import { ToastContainer, toast } from "react-toastify";

const columns = [

    { name: "Title", uid: "title" },
    { name: "Route", uid: "route_title" },
    { name: "From", uid: "destination_from" },
    { name: "To", uid: "destination_to" },
    { name: "Fare", uid: "fare" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function DrinksInventoryList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [destination, setDestination] = useState()
    const [destinations, setDestinations] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const transportActionsApi = useApi(transportApi.transportAction)

    const getDestinations = async () => {
        await transportActionsApi.request({
            "action": "GetEntityDestinations"

        })
    }
    useEffect(() => {
        setdata(destinations)
    }, [destinations])

    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (destinations && destinations.length > 0 && search_param && search_param !== '') {
            setdata(destinations.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(destinations);
        }
    };

    useEffect(() => {
        getDestinations()
    }, [])

    useEffect(() => {

  
              getDestinations()
        
      
    }, [updated])

    const handleEditAction = (item) => {

        setopenEditModal(true)
        setDestination(item)
        setmodalTitle(`Edit ${item.tittle}`)
        setUpdated(false)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new destination")
        setDestination(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/routes/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/routes/delete/${item.id}`)
    }



    useEffect(() => {

        if (transportActionsApi.data && transportActionsApi.data.length) {

            setDestinations(transportActionsApi.data)
        }

        if (transportActionsApi.data && transportActionsApi.data.response_message && transportActionsApi.data.response_code===1) {

            toast.error(transportActionsApi.data.response_message)
        }

        if (transportActionsApi.data && transportActionsApi.data.response_message && transportActionsApi.data.response_code===0) {

            toast.success(transportActionsApi.data.response_message)
        }
       
        console.log("transportActionsApi.data",transportActionsApi.data)
    }, [transportActionsApi.data])

    useEffect(() => {
        getDestinations()
    }, [updated])

    return (
        <div>
        <ToastContainer position="bottom-center" theme="colored" />
            {openEditModal && <DrinksFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={destination} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <DrinksTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default DrinksInventoryList